Cat :: struct {
	name: string,
	age: int,
	color: Cat_Color,
}

Cat_Color :: enum {
	Black,
	White,
	Orange,
	Tabby,
	Calico,
}

Entity :: struct {
	score: string,
	size: int,
	level: Entity_Data,
}

Entity_Data :: enum {
	Value,
	Data,
	Entry,
	Note,
	Item,
}

Record :: struct {
	size: string,
	level: int,
	value: Record_Type,
}

Record_Type :: enum {
	Note,
	Result,
	Data,
	Item,
	Entity,
}

Entry :: struct {
	level: string,
	value: int,
	count: Entry_Kind,
}

Entry_Kind :: enum {
	Item,
	Config,
	Result,
	Entity,
	Record,
}

Data :: struct {
	value: string,
	count: int,
	total: Data_Type,
}

Data_Type :: enum {
	Entity,
	Thing,
	Config,
	Record,
	Entry,
}

Result :: struct {
	count: string,
	total: int,
	amount: Item_Record,
}

Item_Record :: enum {
	Record,
	Value,
	Thing,
	Entry,
	Data,
}

Config :: struct {
	total: string,
	amount: int,
	item: Item_Kind,
}

Item_Kind :: enum {
	Entry,
	Note,
	Value,
	Data,
	Result,
}

Thing :: struct {
	amount: string,
	item: int,
	data: Entity_Data,
}

Entity_Data :: enum {
	Data,
	Item,
	Note,
	Result,
	Config,
}

